<?php
require 'team_bootstrap.php'; require_role('student');
$teamId=(int)($_GET['team']??0);$sid=(int)$_SESSION['user']['id'];$team=null;
$q=$pdo->prepare("SELECT ct.*,o.id offering_id,o.subject_id,o.faculty_id,o.day_name,o.start_time,o.end_time,o.room,o.section,s.code,s.name,s.units,s.description,u.name faculty_name FROM course_teams ct JOIN subject_offerings o ON o.id=ct.offering_id JOIN subjects s ON s.id=o.subject_id LEFT JOIN users u ON u.id=o.faculty_id WHERE ct.id=? LIMIT 1");$q->execute([$teamId]);$team=$q->fetch();
if(!$team || !student_can_access_team($pdo,$teamId,$sid)){http_response_code(403);die('You do not have access to this class team.');}
$tab=$_GET['tab']??'overview'; if(!in_array($tab,['overview','materials','assignments','meetings'],true))$tab='overview'; $error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='submit_assignment'){
  $aid=(int)($_POST['assignment_id']??0);$text=trim($_POST['submission_text']??'');$link=trim($_POST['submission_link']??'');$filePath=null;
  $aq=$pdo->prepare('SELECT * FROM assignments WHERE id=? AND team_id=?');$aq->execute([$aid,$teamId]);$a=$aq->fetch(); if(!$a) die('Assignment not found.');
  if($text==='' && $link==='' && empty($_FILES['submission_file']['name'])) $error='Add a response, link, image, or file before submitting.';
  else { try {
    if($link!=='' && !valid_external_link($link)) throw new Exception('Please enter a valid http:// or https:// submission link.');
    if(!empty($_FILES['submission_file']['name'])) $filePath=team_upload($_FILES['submission_file'],'uploads/assignment_submissions',['pdf','doc','docx','ppt','pptx','xls','xlsx','txt','zip','jpg','jpeg','png','gif','webp'],20*1024*1024,'student_'.$sid.'_assignment_'.$aid);
    $late=($a['due_at'] && strtotime($a['due_at'])<time())?'Late':'Submitted';
    $q=$pdo->prepare("INSERT INTO assignment_submissions(assignment_id,student_id,submission_text,file_path,submission_link,status,submitted_at) VALUES(?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE submission_text=VALUES(submission_text),file_path=COALESCE(VALUES(file_path),file_path),submission_link=VALUES(submission_link),status=VALUES(status),submitted_at=NOW(),updated_at=NOW()");$q->execute([$aid,$sid,$text,$filePath,$link,$late]);
    notify_user($pdo,(int)$team['faculty_id'],'Assignment submitted',$_SESSION['user']['name'].' submitted "'.$a['title'].'" in '.$team['code'].'.','Assignment'); log_transaction($pdo,$sid,'Assignment Submitted',$a['title'].' in '.$team['code'],'assignment',$aid);$success='Assignment submitted successfully.'.($late==='Late'?' It was marked Late.':'');
  } catch(Throwable $ex){$error=$ex->getMessage();}
  }
}
$aq=$pdo->prepare('SELECT a.*, (SELECT status FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) submission_status,(SELECT grade FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) grade,(SELECT feedback FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) feedback,(SELECT submitted_at FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) submitted_at,(SELECT file_path FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) file_path,(SELECT submission_link FROM assignment_submissions x WHERE x.assignment_id=a.id AND x.student_id=?) submission_link FROM assignments a WHERE a.team_id=? ORDER BY COALESCE(a.due_at,"9999-12-31 23:59:59") ASC,a.created_at DESC');$aq->execute([$sid,$sid,$sid,$sid,$sid,$sid,$teamId]);$assignments=$aq->fetchAll();
$mq=$pdo->prepare('SELECT * FROM team_meetings WHERE team_id=? ORDER BY starts_at DESC');$mq->execute([$teamId]);$meetings=$mq->fetchAll();
$matq=$pdo->prepare('SELECT * FROM team_materials WHERE team_id=? ORDER BY (material_type="Syllabus") DESC,created_at DESC');$matq->execute([$teamId]);$materials=$matq->fetchAll();
$recent=$pdo->prepare('SELECT * FROM announcements WHERE (target_subject_id=? OR target_subject_id IS NULL) ORDER BY created_at DESC LIMIT 5');$recent->execute([(int)$team['subject_id']]);$anns=$recent->fetchAll();
require 'header.php';
?>
<section class="section team-page"><div class="team-hero"><div><span class="eyebrow">CLASS TEAM</span><h2><?=e($team['code'])?> — <?=e($team['name'])?></h2><p><?=e($team['faculty_name']?:'Assigned Faculty')?> · Section <?=e($team['section'])?> · <?=e($team['day_name'])?> <?=date('g:i A',strtotime($team['start_time']))?>–<?=date('g:i A',strtotime($team['end_time']))?> · <?=e($team['room'])?></p></div><a class="btn" href="student_teams.php">All Teams</a></div>
<div class="team-tabs"><a class="<?= $tab==='overview'?'active':'' ?>" href="student_team.php?team=<?=$teamId?>&tab=overview">Overview</a><a class="<?= $tab==='materials'?'active':'' ?>" href="student_team.php?team=<?=$teamId?>&tab=materials">Class Materials <span><?=count($materials)?></span></a><a class="<?= $tab==='assignments'?'active':'' ?>" href="student_team.php?team=<?=$teamId?>&tab=assignments">Assignments <span><?=count($assignments)?></span></a><a class="<?= $tab==='meetings'?'active':'' ?>" href="student_team.php?team=<?=$teamId?>&tab=meetings">Meetings <span><?=count($meetings)?></span></a></div>
<?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="auth-alert"><?=e($error)?></div><?php endif;?>
<?php if($tab==='overview'):?><div class="team-columns"><div class="section"><div class="card-head"><h3>Class Overview</h3></div><p><?=e($team['description']?:'Your class team is the central place for class materials, assignments, announcements, and online meetings.')?></p><div class="team-stats"><div><span>Units</span><b><?=e($team['units'])?></b></div><div><span>Section</span><b><?=e($team['section'])?></b></div><div><span>Teacher</span><b><?=e($team['faculty_name']?:'Assigned Faculty')?></b></div></div></div><div class="section"><div class="card-head"><h3>Upcoming</h3></div><?php $up=array_filter($meetings,fn($m)=>strtotime($m['starts_at'])>=time());$up=array_slice($up,0,3);if(!$up):?><p class="muted">No upcoming meetings.</p><?php else:foreach($up as $m):?><div class="list-row"><span><b><?=e($m['title'])?></b><small><?=date('M d, Y · g:i A',strtotime($m['starts_at']))?></small></span><a class="btn small-btn" target="_blank" rel="noopener" href="<?=e($m['meeting_url'])?>">Join</a></div><?php endforeach;endif;?></div></div>
<?php elseif($tab==='materials'):?><div class="section"><div class="card-head"><div><h3>Class Materials</h3><p class="muted">Materials and syllabus posted by <?=e($team['faculty_name']?:'your professor')?>.</p></div></div><?php if(!$materials):?><p class="muted">No class materials have been posted yet.</p><?php endif;?><?php foreach($materials as $m):?><div class="material-card"><div><span class="eyebrow"><?=e(strtoupper($m['material_type']))?></span><h3><?=e($m['title'])?></h3><?php if($m['description']):?><p><?=nl2br(e($m['description']))?></p><?php endif;?><small>Posted <?=date('M d, Y · g:i A',strtotime($m['created_at']))?></small></div><div class="button-group"><?php if($m['file_path']):?><a class="btn" target="_blank" href="<?=e($m['file_path'])?>">View / Download →</a><?php endif;?><?php if($m['link_url']):?><a class="btn secondary-btn" target="_blank" rel="noopener" href="<?=e($m['link_url'])?>">Open Link →</a><?php endif;?></div></div><?php endforeach;?></div>
<?php elseif($tab==='assignments'):?><div class="section"><div class="card-head"><div><h3>Assignments</h3><p class="muted">Assignments posted by <?=e($team['faculty_name']?:'your professor')?>.</p></div></div><?php if(!$assignments):?><p class="muted">No assignments have been posted yet.</p><?php endif;?><?php foreach($assignments as $a):?><div class="assignment-card"><div class="assignment-head"><div><span class="eyebrow"><?=e($a['points'])?> POINTS</span><h3><?=e($a['title'])?></h3></div><span class="status-pill <?=strtolower($a['submission_status']?:'Not submitted')?>"><?=e($a['submission_status']?:'Not submitted')?></span></div><p><?=nl2br(e($a['description']?:'No instructions provided.'))?></p><div class="assignment-meta"><span>Due: <?= $a['due_at']?e(date('M d, Y · g:i A',strtotime($a['due_at']))):'No due date'?></span><?php if($a['grade']!==null):?><span>Grade: <b><?=e($a['grade'])?> / <?=e($a['points'])?></b></span><?php endif;?></div><?php if($a['attachment_path']||$a['attachment_link']):?><div class="attachment-box"><b>Assignment attachment</b><?php if($a['attachment_path']):?><a href="<?=e($a['attachment_path'])?>" target="_blank">📎 View attached file/image →</a><?php endif;?><?php if($a['attachment_link']):?><a href="<?=e($a['attachment_link'])?>" target="_blank" rel="noopener">🔗 Open assignment link →</a><?php endif;?></div><?php endif;?><?php if($a['feedback']):?><div class="info-box"><b>Teacher feedback</b><p><?=nl2br(e($a['feedback']))?></p></div><?php endif;?><form method="post" enctype="multipart/form-data" class="assignment-submit"><input type="hidden" name="action" value="submit_assignment"><input type="hidden" name="assignment_id" value="<?=e($a['id'])?>"><label>Your response<textarea name="submission_text" rows="4" placeholder="Write your answer or submission notes..."><?=e($a['submission_text']??'')?></textarea></label><label>Submission link (optional)<input type="url" name="submission_link" value="<?=e($a['submission_link']??'')?>" placeholder="https://..." /></label><label>Attach file or image (optional)<input type="file" name="submission_file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.zip,.jpg,.jpeg,.png,.gif,.webp"></label><button class="btn" type="submit">Submit Assignment</button><?php if($a['file_path']):?><small>Previous file submitted: <?=e(basename($a['file_path']))?></small><?php endif;?><?php if($a['submission_link']):?><small>Previous link: <a href="<?=e($a['submission_link'])?>" target="_blank" rel="noopener">Open link</a></small><?php endif;?></form></div><?php endforeach;?></div>
<?php else: ?><div class="section"><div class="card-head"><div><h3>Online Class Meetings</h3><p class="muted">Join scheduled group calls for <?=e($team['code'])?>.</p></div></div><?php if(!$meetings):?><p class="muted">No meetings have been scheduled yet.</p><?php endif;?><?php foreach($meetings as $m):?><div class="meeting-card"><div><span class="eyebrow">GROUP CALL</span><h3><?=e($m['title'])?></h3><p><?=e($m['description']?:'Online class meeting')?></p><small><?=date('M d, Y · g:i A',strtotime($m['starts_at']))?> · <?=e($m['duration_minutes'])?> minutes</small></div><a class="btn" target="_blank" rel="noopener" href="<?=e($m['meeting_url'])?>">Join Meeting →</a></div><?php endforeach;?></div><?php endif;?></section>
<?php require 'footer.php';?>
